+<!doctype html>
+<html lang="zh-Hans">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
+  <title>V38 盲评标注工作包</title>
+  <style>
+    :root { color-scheme: light; font-family: "Segoe UI", "Microsoft YaHei", sans-serif; color: #18212f; background: #f3f6fa; }
+    * { box-sizing: border-box; }
+    body { margin: 0; }
+    header { padding: 24px max(20px, calc((100vw - 1260px) / 2)); color: #f7fafc; background: #17263d; }
+    header h1 { margin: 0 0 8px; font-size: 23px; }
+    header p { max-width: 1040px; margin: 6px 0; color: #d2dbea; line-height: 1.55; }
