+    .banner { padding: 14px 16px; margin-bottom: 16px; border-left: 4px solid #bf7b12; border-radius: 7px; background: #fff4db; line-height: 1.55; }
+    .toolbar, .subtoolbar { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; }
+    .toolbar { padding: 12px; margin-bottom: 16px; border: 1px solid #d9e1eb; border-radius: 10px; background: #fff; }
+    button, .file-button { border: 1px solid #9cacc0; border-radius: 7px; padding: 9px 13px; color: #16253b; background: #fff; cursor: pointer; font: inherit; }
+    button.primary { color: #fff; border-color: #2759a5; background: #2759a5; }
+    button:disabled { opacity: .45; cursor: default; }
+    #progress { min-width: 210px; font-weight: 650; }
