+    label.field { display: flex; flex-direction: column; gap: 5px; font-size: 13px; font-weight: 650; }
+    select, textarea { width: 100%; padding: 9px 10px; color: #18212f; border: 1px solid #b9c6d5; border-radius: 7px; background: #fff; font: inherit; }
+    textarea { min-height: 96px; resize: vertical; }
+    details.refs { padding: 9px 11px; margin: 9px 0; border: 1px solid #e0e6ee; border-radius: 8px; background: #fbfcfe; }
+    details.refs summary { cursor: pointer; font-weight: 650; }
+    .ref-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 5px 10px; padding-top: 9px; }
+    .ref-row { display: flex; gap: 7px; align-items: flex-start; font: 12px ui-monospace, Consolas, monospace; overflow-wrap: anywhere; }
